const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function youtubeId(value){try{const u=new URL(value);if(!['https:','http:'].includes(u.protocol))return null;const id=u.hostname==='youtu.be'?u.pathname.slice(1):['www.youtube.com','youtube.com','m.youtube.com'].includes(u.hostname)?u.searchParams.get('v')||u.pathname.match(/^\/(?:shorts|embed)\/([^/]+)/)?.[1]:null;return /^[\w-]{11}$/.test(id||'')?id:null;}catch{return null;}}
export function watchPanel(){return `<section class="studio-paper watch-workspace"><h2>O‘z videongiz bilan mashq</h2><p>YouTube havolasi va mavjud transcriptni kiriting. Gaplarni tinglab, matn bilan kuzatib boring.</p><form id="watch-form"><label>YouTube havolasi<input type="url" name="url" required placeholder="https://www.youtube.com/watch?v=…"></label><label>Transcript / subtitr matni<textarea name="transcript" rows="5" maxlength="20000" placeholder="Video subtitrini shu yerga qo‘ying…" required></textarea></label><button class="btn primary">Darsni ochish</button></form><p id="watch-error" role="alert"></p><div id="watch-lesson"></div><p class="help-text">Havola va matn faqat shu qurilmada saqlanadi. Subtitr avtomatik olinmaydi. Videoni ochishda YouTube bilan aloqa o‘rnatiladi.</p></section>`;}
export function mountWatch(account){const $=s=>document.querySelector(s),key='lexora.watch.'+(account||'guest'),form=$('#watch-form');
const show=data=>{$('#watch-lesson').innerHTML=`<iframe class="watch-frame" title="Inglizcha mashq videosi" src="https://www.youtube-nocookie.com/embed/${data.id}" allow="encrypted-media; picture-in-picture" allowfullscreen></iframe><h3>Transcript</h3><p class="watch-transcript">${data.transcript.split(/(\s+)/).map(word=>/^\s+$/.test(word)?word:`<button type="button" data-context-word="${e(word)}">${e(word)}</button>`).join('')}</p><div id="watch-word" aria-live="polite"></div>`;document.querySelectorAll('[data-context-word]').forEach(b=>b.onclick=()=>{const word=b.dataset.contextWord.replace(/^[^a-z]+|[^a-z]+$/gi,'');$('#watch-word').innerHTML=`<b>${e(word)}</b> <a class="btn" href="https://youglish.com/pronounce/${encodeURIComponent(word)}/english" target="_blank" rel="noopener noreferrer">Boshqa kontekstlarda ko‘rish</a>`;});};
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&youtubeId(saved.url)&&typeof saved.transcript==='string'){form.elements.url.value=saved.url;form.elements.transcript.value=saved.transcript;const b=document.createElement('button');b.type='button';b.className='btn';b.textContent='Saqlangan darsni ochish';b.onclick=()=>{show({...saved,id:youtubeId(saved.url)});b.remove();};$('#watch-lesson').append(b);}}catch{}
form.onsubmit=ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(form)),id=youtubeId(data.url);if(!id){$('#watch-error').textContent='To‘g‘ri YouTube video havolasini kiriting.';return;}$('#watch-error').textContent='';try{localStorage.setItem(key,JSON.stringify(data));}catch{$('#watch-error').textContent='Bu brauzerda saqlash imkoni yo‘q. Dars faqat shu sessiyada qoladi.';}show({...data,id});};}
